<article class="funding-card"><div class="funding-card-top"><span>{{ $round->startup->sector }}</span><time datetime="{{ $round->announced_on->toDateString() }}">{{ $round->announced_on->format('d M Y') }}</time></div><h3><a href="/funding/{{ $round->slug }}">{{ $round->startup->name }}</a></h3><p>{{ \Illuminate\Support\Str::limit($round->startup->description,140) }}</p><div class="funding-amount">{{ \App\Models\FundingRound::money($round->amount_usd) }}</div><div class="funding-round-tags"><span>{{ $round->stage }}</span><span>{{ $round->type }}</span></div><div class="funding-card-investors"><span>LEAD INVESTOR{{ count(array_filter(preg_split('/\R/',$round->lead_investors)))===1 ? '' : 'S' }}</span><p>{{ trim($round->lead_investors) ? implode(' · ',preg_split('/\R/',$round->lead_investors)) : 'Not specified in cited sources' }}</p></div><a class="funding-card-link" href="/funding/{{ $round->slug }}">Round details & sources <b>↗</b></a></article>
